const novo = (seed = 'oils') => createMatch(game, { numPlayers: 2, seed });
const jogar = (m, lugar, type, payload = {}) => applyMove(game, m, lugar, { type, payload });
const ok = (r) => { assert.ok(r.ok, JSON.stringify(r.error)); return r.match; };
const garrafas = (m, lugar) => m.state.jogadores[lugar].banca.filter((x) => x === 2).length;
const cubos = (m, lugar) => m.state.jogadores[lugar].banca.filter((x) => x === 0).length;
// Põe o jogo na pausa depois de um lançamento com estes dados e esta análise (pendente), para o lugar 0.
const comDados = (m, dados, pendente, fn = () => {}) => tweak(m, (s) => { s.vez = 0; s.dados = dados; s.pendente = pendente; s.fase = 'PAUSA'; fn(s); });
const direto = (...combos) => ({ combos, opcoes: null, joker: false });
// Continua depois dos dados; se houver escolha, escolhe a opção que tem esta combinação.
const continuar = (m, combo) => {
  m = ok(jogar(m, 0, 'CONTINUAR'));
  if (m.state.fase === 'COMBO') m = ok(jogar(m, 0, 'ESCOLHER_COMBO', { opcao: m.state.opcoes.findIndex((o) => o.includes(combo)) }));
  return m;
};
const contar = (dados) => dados.reduce((c, d) => ({ ...c, [d]: (c[d] || 0) + 1 }), {});
// Primeiros lançamentos de várias seeds (quem joga lança sem cartas): para ver o que as regras dão com dados reais.
const lancamentos = (n) => Array.from({ length: n }, (_, i) => { const m = novo('l' + i); return ok(jogar(m, m.state.vez, 'LANCAR', { cartas: [] })); });
// Uma opção (lista de combinações) é possível se se consegue dar a cada combinação faces diferentes, com dados que cheguem.
const NECESSIDADE = { DOUBLE: [2], TRIPLE_DOUBLE: [3, 2], QUAD: [4], PENTA: [5], SIX_OF_KIND: [6] };
const possivel = (contagens, combos) => {
  if (!combos.length) return true;
  const [c, ...resto] = combos;
  const faces = Object.keys(contagens);
  const tenta = (need, usadas) => {
    if (!need.length) return possivel(Object.fromEntries(Object.entries(contagens).filter(([f]) => !usadas.includes(f))), resto);
    return faces.some((f) => !usadas.includes(f) && contagens[f] >= need[0] && tenta(need.slice(1), [...usadas, f]));
  };
  return tenta(NECESSIDADE[c], []);
};

