test('Preparação: banca de 6 casas com 2 cubos, 1 carta a cada um, baralho de 6', () => {
  const m = novo();
  for (const j of m.state.jogadores) {
    assert.deepEqual(j.banca, [0, 0, 1, 1, 1, 1]);
    assert.equal(j.mao.length, 1);
    assert.equal(j.reserva, 6);
  }
  assert.equal(m.state.baralho.length, 6, '8 cartas: 2 Sedutoras, 2 Rapazes, 4 Valentões');
  const todas = [...m.state.baralho, ...m.state.jogadores.flatMap((j) => j.mao)];
  assert.deepEqual([...todas].sort(), ['BOY', 'BOY', 'BULLY', 'BULLY', 'BULLY', 'BULLY', 'TEMPTRESS', 'TEMPTRESS']);
  assert.ok([0, 1].includes(m.state.vez));
  assert.throws(() => createMatch(game, { numPlayers: 3, seed: 1 }));
});

test('Cada face só dá uma combinação: todas as opções de um lançamento real são possíveis sem repetir faces', () => {
  let conflitos = 0;
  for (const m of lancamentos(300)) {
    const p = m.state.pendente;
    const contagens = contar(m.state.dados);
    for (const combos of p.opcoes ?? [p.combos]) assert.ok(possivel(contagens, combos), JSON.stringify([m.state.dados, combos]));
    if (p.opcoes) conflitos++;
  }
  assert.ok(conflitos > 0, 'há lançamentos com conflito');
});

test('Conflito: as melhores opções aparecem primeiro; nenhuma opção boa fica atrás de uma que a contém', () => {
  const contem = (maior, menor) => maior.length > menor.length && menor.every((c) => maior.filter((x) => x === c).length >= menor.filter((x) => x === c).length);
  let vistos = 0;
  for (const m of lancamentos(300)) {
    const o = m.state.pendente.opcoes;
    if (!o) continue;
    vistos++;
    o.forEach((a, i) => o.slice(0, i).forEach((b) => assert.ok(!contem(a, b), JSON.stringify([m.state.dados, b, a]))));
    const c = ok(jogar(m, m.state.vez, 'CONTINUAR'));
    assert.equal(c.state.fase, 'COMBO');
    assert.equal(viewFor(game, c, c.state.vez).legal.length, o.length);
  }
  assert.ok(vistos > 0);
});

test('Duplo: compra 1 carta', () => {
  let m = comDados(novo(), [1, 1, 2, 3, 4, 5, 6, 2, 3], direto('DOUBLE'), (s) => { s.jogadores[0].mao = []; });
  const antes = m.state.baralho.length;
  m = ok(jogar(m, 0, 'CONTINUAR'));
  assert.equal(m.state.jogadores[0].mao.length, 1);
  assert.equal(m.state.baralho.length, antes - 1);
});

test('Triplo + Duplo põe uma garrafa numa casa livre', () => {
  const m = continuar(comDados(novo(), [1, 1, 1, 2, 2, 3, 4, 5, 6], direto('TRIPLE_DOUBLE')), 'TRIPLE_DOUBLE');
  assert.equal(garrafas(m, 0), 1);
  assert.equal(m.state.jogadores[0].reserva, 5);
});

test('Quad: abre uma casa com cubo', () => {
  const m = continuar(comDados(novo(), [4, 4, 4, 4, 1, 2, 3, 5, 6], direto('QUAD')), 'QUAD');
  assert.equal(cubos(m, 0), 1);
});

test('Penta: o adversário descarta a mão toda', () => {
  let m = comDados(novo(), [3, 3, 3, 3, 3, 1, 2, 4, 6], direto('PENTA'), (s) => { s.jogadores[1].mao = ['BULLY', 'BOY']; });
  m = continuar(m, 'PENTA');
  assert.deepEqual(m.state.jogadores[1].mao, []);
});

test('Seis: compra 3 cartas', () => {
  let m = comDados(novo(), [2, 2, 2, 2, 2, 2, 1, 3, 4], direto('SIX_OF_KIND'), (s) => { s.jogadores[0].mao = []; });
  const antes = m.state.baralho.length;
  m = ok(jogar(m, 0, 'CONTINUAR'));
  assert.equal(m.state.jogadores[0].mao.length, 3);
  assert.equal(m.state.baralho.length, antes - 3);
});

test('Joker (7 iguais): escolhe qualquer combinação, de Duplo a Seis', () => {
  const opcoes = [['DOUBLE'], ['TRIPLE_DOUBLE'], ['QUAD'], ['PENTA'], ['SIX_OF_KIND']];
  let m = comDados(novo(), [2, 2, 2, 2, 2, 2, 2, 1, 3], { combos: null, opcoes, joker: true });
  m = ok(jogar(m, 0, 'CONTINUAR'));
  assert.equal(m.state.fase, 'COMBO');
  assert.equal(viewFor(game, m, 0).legal.length, 5);
  m = ok(jogar(m, 0, 'ESCOLHER_COMBO', { opcao: 2 }));
  assert.equal(cubos(m, 0), 1);
});

test('Oito iguais: tira 2 cubos vermelhos', () => {
  const m = ok(jogar(comDados(novo(), [6, 6, 6, 6, 6, 6, 6, 6, 1], direto('DOUBLE_QUAD')), 0, 'CONTINUAR'));
  assert.equal(cubos(m, 0), 0);
});

test('Nove iguais: vitória imediata', () => {
  const m = ok(jogar(comDados(novo(), Array(9).fill(4), direto('INSTANT_WIN')), 0, 'CONTINUAR'));
  assert.deepEqual(m.result.winners, [0]);
});

test('Sedutora: com Triplo + Duplo dá 1 garrafa a mais', () => {
  let m = tweak(novo(), (s) => { s.vez = 0; s.jogadores[0].mao = ['TEMPTRESS']; });
  m = ok(jogar(m, 0, 'LANCAR', { cartas: [0] }));
  assert.equal(m.state.sedutoras, 1);
  m = continuar(comDados(m, [1, 1, 1, 2, 2, 3, 4, 5, 6], direto('TRIPLE_DOUBLE'), (s) => { s.sedutoras = 1; }), 'TRIPLE_DOUBLE');
  assert.equal(garrafas(m, 0), 2);
});

test('Rapaz rouba 1 garrafa quando o adversário não tem Valentões', () => {
  const m = ok(jogar(tweak(novo(), (s) => {
    s.vez = 0; s.jogadores[0].mao = ['BOY'];
    s.jogadores[1].banca = [0, 0, 2, 2, 1, 1]; s.jogadores[1].reserva = 4; s.jogadores[1].mao = [];
  }), 0, 'LANCAR', { cartas: [0] }));
  assert.equal(garrafas(m, 1), 1);
});

test('Valentão bloqueia o Rapaz; a decisão é do adversário', () => {
  let m = ok(jogar(tweak(novo(), (s) => {
    s.vez = 0; s.jogadores[0].mao = ['BOY'];
    s.jogadores[1].banca = [0, 0, 2, 2, 1, 1]; s.jogadores[1].reserva = 4; s.jogadores[1].mao = ['BULLY'];
  }), 0, 'LANCAR', { cartas: [0] }));
  assert.equal(m.state.fase, 'DEFESA');
  assert.equal(jogar(m, 0, 'DEFENDER', { valentoes: 1 }).error.code, 'engine.NOT_ACTIVE');
  m = ok(jogar(m, 1, 'DEFENDER', { valentoes: 1 }));
  assert.equal(garrafas(m, 1), 2, 'bloqueado');
  assert.deepEqual(m.state.jogadores[1].mao, []);
  assert.equal(m.state.fase, 'PAUSA', 'depois da defesa, os dados são lançados');
});

test('2 Valentões no próprio turno tiram às cegas uma carta do adversário', () => {
  let m = tweak(novo(), (s) => { s.vez = 0; s.jogadores[0].mao = ['BULLY', 'BULLY']; s.jogadores[1].mao = ['TEMPTRESS', 'BOY']; });
  m = ok(jogar(m, 0, 'LANCAR', { cartas: [0, 1] }));
  assert.equal(m.state.fase, 'ESCOLHA_CEGA');
  assert.equal(game.view(m.state, 0).jogadores[1].mao, undefined, 'não vê a mão do adversário');
  m = ok(jogar(m, 0, 'ESCOLHA_CEGA', { carta: 1 }));
  assert.deepEqual(m.state.jogadores[1].mao, ['TEMPTRESS']);
});

test('Limite de mão: com mais de 3 cartas no fim do turno, descarta até 3', () => {
  let m = comDados(novo(), [2, 2, 2, 2, 2, 2, 1, 3, 4], direto('SIX_OF_KIND'), (s) => { s.jogadores[0].mao = ['BOY']; });
  m = ok(jogar(m, 0, 'CONTINUAR'));
  assert.equal(m.state.jogadores[0].mao.length, 4);
  assert.equal(m.state.fase, 'DESCARTE');
  m = ok(jogar(m, 0, 'DESCARTAR', { carta: 0 }));
  assert.equal(m.state.jogadores[0].mao.length, 3);
  assert.equal(m.state.vez, 1);
});

test('Vitória: a 6.ª garrafa na banca', () => {
  const m = continuar(comDados(novo(), [1, 1, 1, 2, 2, 3, 4, 5, 6], direto('TRIPLE_DOUBLE'), (s) => { s.jogadores[0].banca = [2, 2, 2, 2, 2, 1]; s.jogadores[0].reserva = 1; }), 'TRIPLE_DOUBLE');
  assert.deepEqual(m.result.winners, [0]);
});

test('Simulação: 200 partidas com bots acabam, sem erros', () => {
  const r = simulate(game, { numPlayers: 2, games: 200, seed: 't' });
  assert.equal(r.finished, 200);
  assert.deepEqual(r.failures, []);
});
